<template>
 <div ref="root" class="chain-replay">
  <template v-if="mode==='process'">
   <div class="section-top"><div><h3>供应链情景研判 · 五种推演模型</h3><p>公开事件参数 → 节点受阻 → 交付传播 → 企业供料与价格敞口</p></div><span class="tag">已执行 {{ library.checks.executed_paths }} 条模型路径</span></div>
   <div class="chain-nodes"><span v-for="node in library.network_nodes" :key="node.id" :class="{hit:node.id===event.node}">{{ node.label }}</span></div>
   <div class="model-options" role="group" aria-label="五种供应链情景模型"><button v-for="(m,i) in library.models" :key="m.id" :aria-pressed="context.modelId===m.id" :class="{active:context.modelId===m.id}" @click="setContext('modelId',m.id)"><small>MODEL {{ i+1 }}</small><strong>{{ m.label }}</strong><span>{{ m.kind }}</span><em>已执行情景推演</em></button></div>
   <div class="context-controls"><label>事件参数 <select :value="context.eventId" aria-label="研判事件参数" @change="setContext('eventId',$event.target.value)"><option v-for="e in library.events" :key="e.id" :value="e.id">{{ e.label }}</option></select></label><label>案例方案 <select :value="context.planId" aria-label="研判案例方案" @change="setContext('planId',$event.target.value)"><option v-for="p in scenario.plans" :key="p.id" :value="p.id">{{ p.label }}</option></select></label></div>
   <div class="process-grid"><section><small>01 · 输入及来源</small><h4>{{ event.label }}</h4><p>{{ historicalPeriod(event) }}</p><p>{{ parameterText(event) }}</p><p>需求240 tU／70天；期初80 tU；旧单30＋40 tU；期末目标40 tU。</p><p>新增安排：{{ schedule(plan) }}</p><a v-if="event.source_url" :href="event.source_url" target="_blank" rel="noopener noreferrer">{{ event.publisher }} · 原始披露 ↗</a><a v-if="event.recovery_source_url" :href="event.recovery_source_url" target="_blank" rel="noopener noreferrer">恢复／后续披露 ↗</a></section><section><small>02 · {{ model.short }}计算</small><h4>{{ model.label }}</h4><p>{{ model.definition }}</p><code v-for="formula in model.formulas" :key="formula">{{ formula }}</code><a :href="model.source" target="_blank" rel="noopener noreferrer">方法来源 ↗</a><details><summary>实现与适用范围</summary><p>{{ model.implementation }}</p><p>{{ library.implementation_boundary }}</p></details></section><section><small>03 · 本次实际输出</small><dl class="outputs"><div><dt>最大阶段欠料</dt><dd>{{ number(result.maximum_gap) }}<small> tU</small></dd></div><div><dt>首次欠料／天数</dt><dd class="text-value">{{ result.first_shortage || '无' }} ／ {{ result.shortage_days }}天</dd></div><div><dt>期末净库存</dt><dd>{{ number(result.closing_balance) }}<small> tU · {{ result.closing_target_met?'达标':'未达标' }}</small></dd></div><div><dt>未锁价成本指数</dt><dd>{{ number(result.price_cost_index) }}<small> 基准100</small></dd></div></dl><p>与DES逐日库存路径最大差异：{{ number(result.path_difference_from_des,8) }} tU。</p><p>这项差异用于一致性核对，不是预测准确率。</p></section></div>
   <div class="mapping-note"><b>本案例如何使用该参数：</b>{{ event.mapping }}</div>
   <details class="source-audit"><summary>参数核验记录：3组日级起止、2组长期记录、3组真实价格变动</summary><p>{{ library.checks.duration_fit_type }}；不以3起公告估计事故发生率。旧119条面板未用作119起独立事故训练。{{ library.provenance.audit_summary }}</p><div class="table-scroll"><table><thead><tr><th>历史事件／市场观测</th><th>原始日期／期间</th><th>参数</th><th>核验精度</th><th>来源</th></tr></thead><tbody><tr v-for="e in library.events.slice(0,8)" :key="e.id"><th>{{ e.label }}</th><td>{{ historicalPeriod(e) }}</td><td>{{ parameterText(e) }}</td><td>{{ e.evidence_precision }}</td><td><a :href="e.source_url" target="_blank" rel="noopener noreferrer">{{ e.publisher }} ↗</a></td></tr></tbody></table></div><p class="technical">输入文件SHA256：{{ library.provenance.parameter_sha256 }}</p></details>
  </template>
  <template v-else>
   <div class="section-top"><div><h3>五模型对比 · 历史冲击参数下的供料后果</h3><p>{{ library.scope }}</p></div><span class="tag">8类历史冲击 × 18项方案 × 5模型</span></div>
   <div class="context-controls"><label>共同方案 <select :value="context.planId" aria-label="对比图案例方案" @change="setContext('planId',$event.target.value)"><option v-for="p in scenario.plans" :key="p.id" :value="p.id">{{ p.label }}</option></select></label><label>方案图共同事件 <select :value="context.eventId" aria-label="对比图历史事件" @change="setContext('eventId',$event.target.value)"><option v-for="e in library.events" :key="e.id" :value="e.id">{{ e.label }}</option></select></label><button @click="setContext('eventId','nominal')">按期基准</button><button @click="setContext('eventId','case_14')">复核14天案例</button></div>
   <div class="model-key"><span v-for="(m,i) in library.models" :key="m.id"><i :style="{background:colors[i]}"></i>{{ m.short }}</span><b>颜色代表模型；悬浮逐项查看五个数值</b></div>
   <section class="plot-panel"><div class="plot-top"><h4>① 哪类供应链冲击对本案影响更大</h4><span>点击分组选择下图共同事件</span></div><div class="chart-scroll"><div ref="eventElement" class="event-chart" role="img" aria-label="八类历史冲击参数下五种供应链模型最大缺料量对比"></div></div><p class="axis-note"><b>横轴：</b>监管、加工投入品、道路物流、疫情、商业减停产及历史价格变动；<b>纵轴：</b>{{ library.quantity_definition }} 当前固定新增安排：{{ schedule(plan) }}。历史参数作用于案例的方式见下方记录。</p></section>
   <section class="plot-panel"><div class="plot-top"><h4>② 同一冲击下，哪些采购与到货安排更稳妥</h4><span>{{ event.label }} · {{ parameterText(event) }}</span></div><div class="chart-scroll"><div ref="planElement" class="plan-chart" role="img" aria-label="十八项采购与到货方案的五模型最大缺料量对比"></div></div><p class="axis-note"><b>横轴：</b>新增数量、分批比例及可用到货日组成的18项候选安排；<b>纵轴：</b>同一事件、同一需求下最大欠料量（tU）。新增到货日是检验安排，尚非供方交货承诺。</p></section>
   <div class="consistency"><b>计算一致性：全组最大库存路径差异 {{ number(library.checks.maximum_inventory_difference_tu,8) }} tU</b><p>{{ library.interpretation }} 当前没有额外供应商库存、改道响应或随机失效率，因此五种表示在同一条件下可得到相同值；保留真实相同柱高。</p></div>
   <div class="recommendation"><b>{{ recommendation.title }}</b><p>{{ recommendation.text }}</p></div>
   <details class="numeric-comparison" open><summary>五模型实际数值表 · 最大欠料量tU</summary><div class="table-tabs"><button :class="{active:tableMode==='events'}" @click="tableMode='events'">8类冲击</button><button :class="{active:tableMode==='plans'}" @click="tableMode='plans'">18项方案</button></div><div class="table-scroll comparison-table"><table><thead><tr><th>{{ tableMode==='events'?'冲击参数':'候选安排' }}</th><th v-for="m in library.models" :key="m.id">{{ m.short }}</th><th>期末库存／目标</th></tr></thead><tbody><tr v-for="row in tableRows" :key="row.id" :class="{selected:row.id===(tableMode==='events'?context.eventId:context.planId)}" @click="setContext(tableMode==='events'?'eventId':'planId',row.id)"><th>{{ row.label }}</th><td v-for="m in library.models" :key="m.id">{{ number(row.models[m.id].maximum_gap,4) }}</td><td>{{ number(row.models.discrete_event.closing_balance) }} tU · {{ row.models.discrete_event.closing_target_met?'达标':'未达标' }}</td></tr></tbody></table></div></details>
   <details class="trace"><summary>所选模型的事件映射、订单及70天计算记录</summary><div class="context-controls"><label>追溯模型 <select :value="context.modelId" aria-label="追溯研判模型" @change="setContext('modelId',$event.target.value)"><option v-for="m in library.models" :key="m.id" :value="m.id">{{ m.label }}</option></select></label><b>{{ event.label }} · {{ plan.label }}</b></div><p>{{ historicalPeriod(event) }}；{{ parameterText(event) }}。{{ event.mapping }}</p><p v-if="event.impact_boundary || event.series_note" class="axis-note">原始事实边界：{{ event.impact_boundary || event.series_note }}</p><p v-if="event.duration_boundary" class="axis-note">日期精度：{{ event.duration_boundary }}</p><a v-if="event.source_url" :href="event.source_url" target="_blank" rel="noopener noreferrer">历史参数原始来源 ↗</a><code>{{ library.formula }}</code><div class="table-scroll"><table><thead><tr><th>订单</th><th>数量tU</th><th>计划可用日</th><th>模型交付日</th><th>情景作用范围</th></tr></thead><tbody><tr v-for="o in plan.receipts" :key="o.id"><td>{{ o.id }}</td><td>{{ number(o.quantity) }}</td><td>{{ o.planned_date }}</td><td>{{ deliveryDate(o.id) }}</td><td>{{ o.exposed?'经过受阻节点':'保持案例基准' }}</td></tr></tbody></table></div><p>所选模型执行状态更新 {{ result.operations }} 次；成本指数 {{ number(result.price_cost_index) }}。价格情景未设置预算约束，价格变化不自动改变数量。</p><details><summary>展开70天逐日库存台账</summary><div class="table-scroll daily-table"><table><thead><tr><th>日期</th><th>当日到货tU</th><th>当日需求tU</th><th>净库存tU</th><th>累计欠料tU</th></tr></thead><tbody><tr v-for="(balance,i) in result.inventory_path" :key="i"><td>{{ dayDate(i) }}</td><td>{{ number(result.receipt_path[i]) }}</td><td>{{ number(240/70,4) }}</td><td>{{ number(balance,4) }}</td><td>{{ number(Math.max(0,-balance),4) }}</td></tr></tbody></table></div></details></details>
  </template>
 </div>
</template>

<script setup>
import {computed,ref,watch,nextTick,onMounted,onUnmounted} from 'vue'
import * as echarts from 'echarts'
const props=defineProps({library:{type:Object,required:true},mode:{type:String,default:'results'},modelValue:{type:Object,required:true}})
const emit=defineEmits(['update:modelValue'])
const root=ref(null),eventElement=ref(null),planElement=ref(null),tableMode=ref('plans')
const colors=['#2563eb','#0d9488','#d97706','#7c3aed','#dc6b4c']
const context=computed(()=>props.modelValue)
const event=computed(()=>props.library.events.find(e=>e.id===context.value.eventId) || props.library.events[0])
const scenario=computed(()=>props.library.scenarios.find(s=>s.id===event.value.id))
const plan=computed(()=>scenario.value.plans.find(p=>p.id===context.value.planId) || scenario.value.plans[0])
const model=computed(()=>props.library.models.find(m=>m.id===context.value.modelId) || props.library.models[0])
const result=computed(()=>plan.value.models[model.value.id])
const number=(v,digits=2)=>v==null?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:digits})
const setContext=(key,value)=>emit('update:modelValue',{...context.value,[key]:value})
const schedule=p=>p.new_receipts.length?p.new_receipts.map(o=>`${o.quantity} tU / ${o.date.slice(5)}`).join('；'):'不新增'
const dayDate=i=>new Date(Date.parse(props.library.case.start+'T00:00:00Z')+i*86400000).toISOString().slice(0,10)
const deliveryDate=id=>result.value.delivery_days[id]==null?'季度内未交付':dayDate(result.value.delivery_days[id])
const historicalPeriod=e=>(e.start_date || e.start_period || '案例条件')+' → '+(e.end_date || e.end_period || (e.kind==='user_case_condition'?'检验14天':e.kind==='nominal'?'按期':'日级恢复日未披露'))
const parameterText=e=>e.node==='market'?`${e.start_value} → ${e.end_value} 美元/lb U₃O₈；${number(e.change_percent)}%`:`${e.duration_days==null && e.replay_days===70?'≥':''}${e.replay_days}天${e.duration_days==null && e.replay_days===70?'（只取70天窗口）':''}`
const eventRows=computed(()=>props.library.events.slice(0,8).map(e=>({id:e.id,label:e.label,models:plan.value.id==='frontload130'?props.library.frontload_cross_event[context.value.eventId][e.id]:props.library.scenarios.find(s=>s.id===e.id).plans.find(p=>p.id===plan.value.id).models})))
const tableRows=computed(()=>tableMode.value==='events'?eventRows.value:scenario.value.plans)
const recommendation=computed(()=>{
 const original=scenario.value.plans.find(p=>p.id==='staged130'),front=scenario.value.plans.find(p=>p.id==='frontload130'),r=original.models.discrete_event,f=front.models.discrete_event
 if(event.value.node==='market')return {title:`价格成本指数为${number(result.value.price_cost_index)}，物理缺料量另行计算`,text:'本情景只改变未锁价部分的价格暴露；没有企业预算上限或现金约束，不能据此假定涨价必然导致采购数量减少。130 tU净需求不会因价格改变。'}
 if(r.maximum_gap===0 && r.closing_target_met)return {title:'原130 tU分批方案在本条件下无阶段缺料、期末达标',text:'这只适用于已说明的事件作用范围和到货安排。仍须同时核验供方备货、通道、验收可用日及价格敞口。'}
 return {title:`同为130 tU，前置${number(front.frontload_quantity)} tU后最大缺料由${number(r.maximum_gap)}变为${number(f.maximum_gap)} tU`,text:`反求安排：${schedule(front)}。前置量从原两批调出；期末${number(f.closing_balance)} tU，${f.closing_target_met?'达到':'未达到'}40 tU目标。模型给出所需到货目标，实际供货窗口须落实。`}
})
const axisLabel=p=>({no_new:'不新增\n0 tU',qty80:'80 tU\n70＋10',qty100:'100 tU\n70＋30',qty120:'120 tU\n70＋50',staged130:'130 tU\n70＋60',qty140:'140 tU\n70＋70',qty160:'160 tU\n100＋60',once130:'130 tU\n一次到货',split30:'130 tU\n30＋100',split50:'130 tU\n50＋80',split90:'130 tU\n90＋40',split110:'130 tU\n110＋20',early05:'130 tU\n首批11/05',early09:'130 tU\n首批11/09',late20:'130 tU\n首批11/20',late01:'130 tU\n首批12/01',three_batches:'130 tU\n40＋40＋50',frontload130:`130 tU\n前置${number(p.frontload_quantity)}`})[p.id]
let eventChart,planChart,observer,alive=true
function chartOption(labels,rows){
 const maximum=Math.max(10,Math.ceil(Math.max(...rows.flatMap(r=>props.library.models.map(m=>r.models[m.id].maximum_gap)))/10)*10)
 return {animation:false,color:colors,grid:{left:64,right:24,top:40,bottom:68},tooltip:{trigger:'axis',confine:true,axisPointer:{type:'shadow'},formatter:items=>{
  const row=rows[items[0].dataIndex]
  return `<b>${row.label}</b><br/>`+items.map(it=>`${it.marker}${it.seriesName}：<b>${number(it.value,4)} tU</b>`).join('<br/>')+`<br/>期末净库存：${number(row.models.discrete_event.closing_balance)} tU`
 }},xAxis:{type:'category',data:labels,axisLabel:{fontSize:11,interval:0,lineHeight:17},axisTick:{alignWithLabel:true}},yAxis:{type:'value',name:'最大累计欠料（tU）',min:0,max:maximum,axisLabel:{fontSize:11},splitLine:{lineStyle:{color:'#e8eef6'}}},series:props.library.models.map((m,i)=>({name:m.short,type:'bar',barMaxWidth:15,barGap:'10%',data:rows.map(r=>r.models[m.id].maximum_gap),itemStyle:{color:colors[i],borderRadius:[2,2,0,0]},label:{show:m.id===context.value.modelId,position:'top',fontSize:10,formatter:p=>number(p.value,2)}}))}
}
async function render(){
 await nextTick();if(!alive||props.mode!=='results'||!eventElement.value||!planElement.value)return
 eventChart ||= echarts.init(eventElement.value);planChart ||= echarts.init(planElement.value)
 eventChart.setOption(chartOption(props.library.events.slice(0,8).map(e=>e.axis_label),eventRows.value),true)
 planChart.setOption(chartOption(scenario.value.plans.map(axisLabel),scenario.value.plans),true)
 eventChart.off('click');eventChart.on('click',p=>{if(p.componentType==='series')setContext('eventId',eventRows.value[p.dataIndex].id)})
 planChart.off('click');planChart.on('click',p=>{if(p.componentType==='series')setContext('planId',scenario.value.plans[p.dataIndex].id)})
 eventChart.resize();planChart.resize()
}
watch([()=>props.modelValue,()=>props.library],render,{deep:true})
onMounted(()=>{observer=new ResizeObserver(()=>{eventChart?.resize();planChart?.resize()});observer.observe(root.value);render()})
onUnmounted(()=>{alive=false;observer?.disconnect();eventChart?.dispose();planChart?.dispose()})
</script>

<style scoped>
